import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { useTranslation } from 'react-i18next';
import toast from 'react-hot-toast';
import Navbar from '../../components/Navbar';

const ROLE_REDIRECTS = { citizen: '/citizen/dashboard', police: '/police/dashboard', municipal: '/municipal/dashboard', admin: '/admin/dashboard' };

const LoginPage = () => {
    const { login } = useAuth();
    const { t } = useTranslation();
    const navigate = useNavigate();
    const [form, setForm] = useState({ email: '', password: '' });
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError('');
        try {
            const data = await login(form);
            toast.success(`Welcome back, ${data.user.name}!`);
            navigate(ROLE_REDIRECTS[data.user.role] || '/');
        } catch (err) {
            setError(err.response?.data?.message || 'Login failed. Please try again.');
        } finally { setLoading(false); }
    };

    const fillDemo = (email, pass) => setForm({ email, password: pass });

    return (
        <div className="min-h-screen bg-gradient-to-br from-primary-50 via-white to-blue-50">
            <Navbar />
            <div className="flex items-center justify-center py-12 px-4">
                <div className="w-full max-w-md">
                    <div className="text-center mb-8">
                        <div className="inline-flex items-center justify-center w-14 h-14 bg-primary-600 rounded-2xl mb-4 shadow-lg">
                            <span className="text-white text-2xl font-bold">eN</span>
                        </div>
                        <h1 className="text-2xl font-bold text-gray-900">{t('auth.loginTitle')}</h1>
                        <p className="text-gray-500 text-sm mt-1">{t('auth.tagline')}</p>
                    </div>

                    <div className="card">
                        {error && (
                            <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg text-sm text-red-600">{error}</div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">{t('auth.email')}</label>
                                <input name="email" type="email" required value={form.email} onChange={handleChange}
                                    className="input-field" placeholder="you@example.com" id="email" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">{t('auth.password')}</label>
                                <input name="password" type="password" required value={form.password} onChange={handleChange}
                                    className="input-field" placeholder="••••••••" id="password" />
                            </div>
                            <button type="submit" disabled={loading} className="btn-primary w-full mt-2" id="login-btn">
                                {loading ? 'Signing in...' : t('auth.loginBtn')}
                            </button>
                        </form>

                        <div className="mt-5 pt-4 border-t border-gray-100">
                            <p className="text-xs text-gray-400 text-center mb-2 font-medium">Quick Demo Login</p>
                            <div className="grid grid-cols-2 gap-2">
                                {[
                                    { label: '👤 Citizen', email: 'citizen1@example.com', pass: 'Citizen@1234' },
                                    { label: '🔴 Police', email: 'police@enagar.gov.in', pass: 'Police@1234' },
                                    { label: '🏗 Municipal', email: 'municipal@enagar.gov.in', pass: 'Municipal@1234' },
                                    { label: '⚙ Admin', email: 'admin@enagar.gov.in', pass: 'Admin@1234' },
                                ].map(({ label, email, pass }) => (
                                    <button key={email} type="button" onClick={() => fillDemo(email, pass)}
                                        className="text-xs px-2 py-1.5 bg-gray-50 hover:bg-gray-100 border border-gray-200 rounded-lg text-gray-600 transition-colors">
                                        {label}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <p className="mt-4 text-center text-sm text-gray-500">
                            {t('auth.noAccount')}{' '}
                            <Link to="/register" className="text-primary-600 hover:text-primary-700 font-medium">Create account</Link>
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default LoginPage;
